from cache import make_key
import uuid

def compute():
    return uuid.uuid4()

def score(store, job_text, profile_version, criteria_version, compute):
    k=make_key(job_text,profile_version,criteria_version)
    if k not in store: store[k]=compute()
    return store[k]
